import type { DrawerProps } from "./drawer.types";

import React, { forwardRef } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import * as RadixDialog from "@radix-ui/react-dialog";
import { usePortalContainer } from "@hooks/use-portal-container";

import { DrawerClasses, StyledDrawer, StyledDrawerOverlay } from "./drawer.styles";
import { useDrawerContext } from "./hooks/use-drawer-context";

export type DrawerImplementationProps = Omit<DrawerProps, "children"> & {
  drawerTrigger: React.ReactNode;
  drawerContent: React.ReactNode;
  drawerClose: React.ReactNode;
};

export const DrawerOverlay = forwardRef<HTMLDivElement, DrawerImplementationProps>(
  (
    {
      className,
      containerElement,
      position = "start",
      variant = "default",
      padding = true,
      styleSlots,
      drawerTrigger,
      drawerContent,
      drawerClose,
      onEscapeKeyDown,
      onInteractOutside,
      onPointerDownOutside,
      onOpenAutoFocus,
      onCloseAutoFocus,
      ...props
    },
    ref,
  ) => {
    const { open, onOpenChange, modal, dismissible } = useDrawerContext();
    const theme = useTheme();
    const { resolvedContainer, isScoped } = usePortalContainer(containerElement);

    return (
      <RadixDialog.Root modal={modal} open={open} onOpenChange={onOpenChange}>
        {drawerTrigger}
        <RadixDialog.Portal container={resolvedContainer}>
          <StyledDrawerOverlay
            className={DrawerClasses.overlay}
            currentTheme={theme}
            data-textura-scoped={isScoped}
            styleSlots={styleSlots}
            variant={variant}
          />
          <StyledDrawer
            ref={ref}
            aria-describedby={undefined}
            className={clsx(DrawerClasses.root, DrawerClasses.body, className, {
              [DrawerClasses.start]: position === "start",
              [DrawerClasses.end]: position === "end",
              [DrawerClasses.top]: position === "top",
              [DrawerClasses.bottom]: position === "bottom",
              [DrawerClasses.padding]: padding,
            })}
            currentTheme={theme}
            data-textura-scoped={isScoped}
            styleSlots={styleSlots}
            variant={variant}
            onCloseAutoFocus={onCloseAutoFocus}
            onEscapeKeyDown={(e) => {
              if (!dismissible) {
                e.preventDefault();
              }
              onEscapeKeyDown?.(e);
            }}
            onInteractOutside={(e) => {
              if (!dismissible) {
                e.preventDefault();
              }
              onInteractOutside?.(e);
            }}
            onOpenAutoFocus={onOpenAutoFocus}
            onPointerDownOutside={(e) => {
              if (!dismissible) {
                e.preventDefault();
              }
              onPointerDownOutside?.(e);
            }}
            {...props}
          >
            {drawerContent}
            {drawerClose}
          </StyledDrawer>
        </RadixDialog.Portal>
      </RadixDialog.Root>
    );
  },
);

DrawerOverlay.displayName = "DrawerOverlay";
